<?php $page_title='Semua KRS'; require_once __DIR__.'/../includes/header.php'; require_login(['admin']); $rows=db()->query('SELECT k.id,m.npm,m.nama mahasiswa,mk.kode,mk.nama mata_kuliah,mk.sks,kl.nama_kelas,t.tahun,t.semester FROM krs k JOIN mahasiswa m ON m.id=k.id_mahasiswa JOIN mata_kuliah mk ON mk.id=k.id_mk JOIN kelas kl ON kl.id=k.id_kelas JOIN tahun_akademik t ON t.id=k.id_tahun_akademik ORDER BY k.id DESC')->fetchAll(); ?><h3 class="mb-4">Semua KRS</h3><div class="card p-4"><div class="table-responsive"><table class="table datatable"><thead><tr><th>NPM</th><th>Mahasiswa</th><th>Mata Kuliah</th><th>Kelas</th><th>SKS</th><th>Periode</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['npm'])?></td><td><?=e($r['mahasiswa'])?></td><td><?=e($r['kode'].' — '.$r['mata_kuliah'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=$r['sks']?></td><td><?=e($r['tahun'].' '.$r['semester'])?></td></tr><?php endforeach?></tbody></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
